[
  {
    "ce_understood_harm": "if it reaches them some might never walk off that track",
    "ae_welfare_concern": "Strangers or not, their lives matter to me",
    "sys_rule_justification": "When you can save someone without hurting anyone else, you're obligated to do it",
    "sys_consequence_reasoning": "When you can save someone without hurting anyone else"
  },
  {
    "ce_understood_harm": "the train crushing bones, families getting a phone call",
    "ae_welfare_concern": "I care what happens to them",
    "sys_rule_justification": "standing by while people die, when stopping it costs nothing, is simply wrong",
    "sys_consequence_reasoning": "stopping it costs nothing",
    "pd_decision_conflict": "I'd probably still feel shaky afterward, just thinking about what almost happened"
  },
  {
    "ce_understood_harm": "five people were one moment from being killed or maimed",
    "ae_welfare_concern": "I don't want that for them",
    "sys_rule_justification": "if saving a life puts no one at risk, you don't get to stay out of it",
    "sys_consequence_reasoning": "saving a life puts no one at risk"
  },
  {
    "ce_understood_harm": "leaves nothing good behind: broken bodies, grieving families",
    "ae_welfare_concern": "Those men and women matter",
    "sys_rule_justification": "duty extends to anyone standing near a lever"
  },
  {
    "pd_harm_distress": "My hand would probably tremble",
    "ce_understood_harm": "the workers would be struck and badly hurt or killed",
    "ae_welfare_concern": "I can't bear the thought of that happening to them",
    "sys_rule_justification": "I hold that you must help when you safely can",
    "sys_consequence_reasoning": "the siding is empty and the barrier stops it"
  },
  {
    "sys_rule_justification": "Those five have a right not to be run down",
    "sys_consequence_reasoning": "without costing anyone anything",
    "ae_welfare_concern": "Their safety matters to me",
    "ce_understood_harm": "the impact and the injuries, the lives cut off"
  },
  {
    "sys_rule_justification": "you help your neighbor when it's in your power",
    "ce_understood_harm": "Five workers about to be hit by a train, maybe killed",
    "pd_harm_distress": "I'd feel sick if they got hurt and I'd just watched",
    "ae_welfare_concern": "I'd feel sick if they got hurt"
  },
  {
    "ce_understood_harm": "If that train hits them, someone waits at home for a person who never arrives",
    "ae_welfare_concern": "I can't shrug that off",
    "sys_rule_justification": "if you can prevent a death at no cost, you have to",
    "sys_consequence_reasoning": "prevent a death at no cost"
  },
  {
    "ce_understood_harm": "Letting five people be struck down",
    "sys_rule_justification": "You don't leave people to die if saving them harms no one",
    "ae_welfare_concern": "I care whether they live",
    "sys_consequence_reasoning": "saving them harms no one"
  },
  {
    "ce_understood_harm": "five workers get hit, some possibly killed",
    "pd_personal_consequence_anxiety": "I'm not sure I could live with that",
    "sys_rule_justification": "failing to rescue when it's safe and easy is its own kind of wrongdoing",
    "sys_consequence_reasoning": "safe and easy"
  }
]
